# Client API Enhancement: Agent Search Methods

Looking at the client-side API module, I need to add new methods to expose the agent search functionality to the frontend, alongside the existing `aiSearch` method.

```js client/src/api/api.js
knowledge: {
  status() {
    return API.get('/api/knowledge/status')
  },
  files() {
    return API.get('/api/knowledge/files')
  },
  reload() {
    return API.get('/api/knowledge/reload')
  },
  reloadFolder(path) {
    return API.post(`/api/knowledge/reload-path`, { path })
  },
  indexFilesBackground(filePaths) {
    if (!API.socket) {
      throw new Error('Socket not connected')
    }
    return new Promise((resolve, reject) => {
      const timeoutId = setTimeout(() => {
        reject(new Error('Index operation timed out'))
      }, 30000)

      API.socket.emit('codx-junior-index-knowledge', {
        file_paths: filePaths,
        codx_path: API.activeProject?.codx_path
      }, (response) => {
        clearTimeout(timeoutId)
        if (response?.error) {
          reject(new Error(response.error))
        } else {
          resolve(response)
        }
      })
    })
  },
  search({
    searchTerm: search_term,
    searchType: search_type,
    documentSearchType: document_search_type,
    cutoffScore: document_cutoff_score,
    cutoffRag: document_cutoff_rag,
    documentCount: document_count
  }) {
    return API.post(`/api/knowledge/reload-search`, {
      search_term,
      search_type,
      document_search_type,
      document_cutoff_score,
      document_cutoff_rag,
      document_count
    })
  },
  aiSearch(query) {
    return API.get(`/api/knowledge/ai-search?query=${encodeURIComponent(query)}`)
  },
  agentSearch(request, maxIterations = 3) {
    return API.get(
      `/api/knowledge/agent-search?request=${encodeURIComponent(request)}&max_iterations=${maxIterations}`
    )
  },
  agentSearchBackground(request, maxIterations = 3) {
    if (!API.socket) {
      throw new Error('Socket not connected')
    }
    return new Promise((resolve, reject) => {
      const timeoutId = setTimeout(() => {
        reject(new Error('Agent search operation timed out'))
      }, 300000) // 5 minute timeout for long-running searches

      API.socket.emit('codx-junior-agent-search', {
        request: request,
        max_iterations: maxIterations
      }, (response) => {
        clearTimeout(timeoutId)
        if (response?.error) {
          reject(new Error(response.error))
        } else {
          resolve(response)
        }
      })
    })
  },
  onAgentSearchProgress(callback) {
    if (!API.socket) {
      throw new Error('Socket not connected')
    }
    API.socket.on('codx-junior-agent-search-progress', callback)
  },
  onAgentSearchComplete(callback) {
    if (!API.socket) {
      throw new Error('Socket not connected')
    }
    API.socket.on('codx-junior-agent-search-complete', callback)
  },
  onAgentSearchError(callback) {
    if (!API.socket) {
      throw new Error('Socket not connected')
    }
    API.socket.on('codx-junior-agent-search-error', callback)
  },
  delete(sources) {
    return API.post(`/api/knowledge/delete`, { sources })
  },
  deleteIndex(index) {
    return API.del(`/api/knowledge/delete?index=${index}`)
  },
  keywords() {
    return API.get(`/api/knowledge/keywords`)
  },
  searchKeywords(searchQuery) {
    return API.get(`/api/knowledge/keywords?query=${searchQuery}`)
  },
  query(searchQuery) {
    return API.get(`/api/project/search?query=${searchQuery}`)
  },
  summary() {
    return API.get(`/api/knowledge/summary`)
  },
  rebuildSummary() {
    return API.post(`/api/knowledge/summary/rebuild`, {})
  },
  deleteSummary() {
    return API.delete(`/api/knowledge/summary`)
  }
},
```

## Client Usage Examples

### HTTP-based Agent Search

```javascript
// Synchronous REST call (good for quick, small requests)
const plan = await API.knowledge.agentSearch(
  'Add email notification system to user signup flow',
  3 // max iterations
)

console.log('Overview:', plan.overview)
console.log('Files to read:', plan.files_to_read)
console.log('Files to modify:', plan.files_to_modify)
console.log('Files to create:', plan.files_to_create)
console.log('Supporting documents:', plan.documents.length)
```

### Socket-based Agent Search with Progress Tracking

```javascript
// Asynchronous socket-based call (good for long-running searches)

// Set up event listeners BEFORE starting the search
API.knowledge.onAgentSearchProgress((data) => {
  console.log(`Progress: Iteration ${data.iteration}`)
  console.log(`  Documents found: ${data.documents_found}`)
  console.log(`  Sufficient: ${data.is_sufficient}`)
  console.log(`  Message: ${data.message}`)
})

API.knowledge.onAgentSearchComplete((data) => {
  if (data.status === 'success') {
    const plan = data.plan
    console.log('Plan generated successfully!')
    console.log(`  Files to read: ${plan.files_to_read.length}`)
    console.log(`  Files to modify: ${plan.files_to_modify.length}`)
    console.log(`  Files to create: ${plan.files_to_create.length}`)
    console.log(`  Total iterations: ${plan.total_iterations}`)
    // Display plan to user...
  }
})

API.knowledge.onAgentSearchError((data) => {
  console.error('Search failed:', data.message)
  // Show error to user...
})

// Start the search
try {
  await API.knowledge.agentSearchBackground(
    'Refactor authentication system to use OAuth2',
    5 // max iterations
  )
} catch (error) {
  console.error('Failed to initiate agent search:', error)
}
```

### Comparison: REST vs Socket

```javascript
// REST approach - simpler, synchronous, limited to ~30s
const plan1 = await API.knowledge.agentSearch('Simple request')

// Socket approach - more complex, asynchronous, supports progress tracking
// Set up listeners first...
API.knowledge.onAgentSearchComplete((data) => { /* ... */ })
// Then emit the request...
await API.knowledge.agentSearchBackground('Complex request')
```

## Integration with UI Components

```javascript
// Example: React component using agent search
async function AgentPlanComponent({ request }) {
  const [plan, setPlan] = useState(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(null)

  useEffect(() => {
    // Set up socket listeners
    API.knowledge.onAgentSearchComplete((data) => {
      if (data.status === 'success') {
        setPlan(data.plan)
        setLoading(false)
      }
    })

    API.knowledge.onAgentSearchError((data) => {
      setError(data.message)
      setLoading(false)
    })
  }, [])

  async function handleSearch() {
    setLoading(true)
    setError(null)
    try {
      await API.knowledge.agentSearchBackground(request, 3)
    } catch (err) {
      setError(err.message)
      setLoading(false)
    }
  }

  return (
    <div>
      <button onClick={handleSearch} disabled={loading}>
        {loading ? 'Searching...' : 'Generate Plan'}
      </button>
      {error && <div className="error">{error}</div>}
      {plan && (
        <div>
          <h3>{plan.overview}</h3>
          <ul>
            <li>Files to read: {plan.files_to_read.length}</li>
            <li>Files to modify: {plan.files_to_modify.length}</li>
            <li>Files to create: {plan.files_to_create.length}</li>
          </ul>
        </div>
      )}
    </div>
  )
}
```

## API Method Reference

| Method | Type | Purpose | Best For |
|--------|------|---------|----------|
| `agentSearch()` | HTTP GET | Synchronous agent search | Quick requests, simple UI |
| `agentSearchBackground()` | Socket | Asynchronous agent search | Long-running searches, progress tracking |
| `onAgentSearchProgress()` | Socket | Listen for iteration updates | Real-time UI updates |
| `onAgentSearchComplete()` | Socket | Listen for plan completion | Displaying final results |
| `onAgentSearchError()` | Socket | Listen for errors | Error handling |

## Key Differences from AI Search

- **`aiSearch()`**: Question-answering, returns free-text answer
- **`agentSearch()`**: Synchronous REST call, structured resource plan output
- **`agentSearchBackground()`**: Asynchronous socket-based, supports progress events

